import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            int[] readTime = new int[n];
            int[] writeTime = new int[n];
            int sumRead = 0;
            int sumWrite = 0;

            for (int i = 0; i < n; i++) {
                readTime[i] = fs.nextInt();
                writeTime[i] = fs.nextInt();
                sumRead += readTime[i];
                sumWrite += writeTime[i];
            }

            // dp[a] = bitset of possible b values:
            // Ami has total reading time a, Mami has total reading time b.
            // For every book, one child gets reading time r and the other gets writing time w.
            boolean[][] dp = new boolean[sumRead + 1][sumRead + 1];
            dp[0][0] = true;

            int processedRead = 0;
            for (int i = 0; i < n; i++) {
                int r = readTime[i];
                boolean[][] next = new boolean[sumRead + 1][sumRead + 1];

                for (int a = 0; a <= processedRead; a++) {
                    for (int b = 0; b <= processedRead; b++) {
                        if (!dp[a][b]) continue;

                        // Ami reads this book first, Mami reads it second
                        next[a + r][b] = true;

                        // Mami reads this book first, Ami reads it second
                        next[a][b + r] = true;
                    }
                }

                dp = next;
                processedRead += r;
            }

            int answer = Integer.MAX_VALUE;

            for (int a = 0; a <= sumRead; a++) {
                for (int b = 0; b <= sumRead; b++) {
                    if (!dp[a][b]) continue;

                    // Ami total time = reading assigned first + writing assigned second
                    // = a + (sumWrite - write assigned to Mami second)
                    // But since assignment is per book and only reading sums are tracked,
                    // use equivalent formulation:
                    // completion time is max(Ami total, Mami total)
                    //
                    // If Ami reads first on a set S:
                    // Ami time = sum_{i in S} r_i + sum_{i not in S} w_i
                    // Mami time = sum_{i not in S} r_i + sum_{i in S} w_i
                    //
                    // Let a = sum_{i in S} r_i, b = sum_{i not in S} r_i = sumRead - a.
                    // We also need writing partition, but since each chosen side for a book
                    // also determines who writes, the correct classical solution actually
                    // requires subset sum over differences d_i = r_i - w_i.
                    // We can derive from a alone:
                    // Ami time = a + (sumWrite - ws)
                    // Mami time = (sumRead - a) + ws
                    // where ws is sum of w_i in S.
                    // So reading-only DP is insufficient.
                }
            }

            // Correct DP on transformed weights:
            // Let S be books Ami reads first.
            // Ami time = sumW + sum_{i in S}(r_i - w_i)
            // Mami time = sumR - sum_{i in S}(r_i - w_i)
            // Need minimize max(sumW + x, sumR - x), where x is achievable subset sum of diff.
            int offset = 0;
            for (int i = 0; i < n; i++) offset += Math.abs(readTime[i] - writeTime[i]);
            boolean[] poss = new boolean[2 * offset + 1];
            int base = offset;
            poss[base] = true;

            int low = 0, high = 0;
            for (int i = 0; i < n; i++) {
                int d = readTime[i] - writeTime[i];
                boolean[] next = new boolean[2 * offset + 1];
                for (int s = base + low; s <= base + high; s++) {
                    if (!poss[s]) continue;
                    next[s + d] = true; // book in S
                    next[s] = true;     // wait, this would mean not choosing? incorrect
                }
                // Need subset partition: choose +d if in S, else 0 is not enough.
                // Better formulation:
                // x = sum_{i in S} d_i, S arbitrary subset.
                // This is exactly subset sum over d_i values.
                // So transitions are choose or not choose.
                poss = next;
                low = Math.min(low, low + d);
                high = Math.max(high, high + d);
            }

            answer = Integer.MAX_VALUE;
            for (int s = 0; s < poss.length; s++) {
                if (!poss[s]) continue;
                int x = s - base;
                int ami = sumWrite + x;
                int mami = sumRead - x;
                answer = Math.min(answer, Math.max(ami, mami));
            }

            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int read;
    int write;
} Book;

int compare(const void *a, const void *b) {
    Book *bookA = (Book *)a;
    Book *bookB = (Book *)b;
    // Sort by writing time descending to minimize idle time
    return bookB->write - bookA->write;
}

int max(int a, int b) {
    return a > b ? a : b;
}

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        Book books[n];
        for (int i = 0; i < n; i++) {
            scanf("%d %d", &books[i].read, &books[i].write);
        }

        // Sort books by writing time descending
        qsort(books, n, sizeof(Book), compare);

        int total_read_time = 0;
        int total_time = 0;

        for (int i = 0; i < n; i++) {
            total_read_time += books[i].read;
            // The total time is max of current total time and 
            // total reading time plus the writing time of this book
            total_time = max(total_time, total_read_time + books[i].write);
        }

        printf("%d\n", total_time);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

int N;
int r[10], w[10];
int best;

// ami_done: bitmask of books ami has read
// mami_done: bitmask of books mami has read
// ami_t: when ami is free (for reading)
// mami_t: when mami is free
// book_t[i]: when book i is free (not being read)
// ami_finish: earliest ami can finish all writing
// mami_finish: earliest mami can finish all writing

void solve(int ami_done, int mami_done, int ami_t, int mami_t, int *book_t, int ami_wt, int mami_wt) {
    if (ami_done == (1<<N)-1 && mami_done == (1<<N)-1) {
        int fin = ami_wt > mami_wt ? ami_wt : mami_wt;
        if (fin < best) best = fin;
        return;
    }
    // Try assigning next read to ami or mami
    for (int who = 0; who < 2; who++) {
        int done = who == 0 ? ami_done : mami_done;
        if (done == (1<<N)-1) continue;
        for (int i = 0; i < N; i++) {
            if (done & (1<<i)) continue;
            int t = who == 0 ? ami_t : mami_t;
            int start = t > book_t[i] ? t : book_t[i];
            int end = start + r[i];
            int new_book_t[10];
            memcpy(new_book_t, book_t, sizeof(int)*N);
            new_book_t[i] = end;
            if (who == 0) {
                solve(ami_done|(1<<i), mami_done, end, mami_t, new_book_t, ami_wt > end ? ami_wt + w[i] : end + w[i], mami_wt);
            } else {
                solve(ami_done, mami_done|(1<<i), ami_t, end, new_book_t, ami_wt, mami_wt > end ? mami_wt + w[i] : end + w[i]);
            }
        }
    }
}

int main() {
    while (scanf("%d", &N) == 1 && N) {
        for (int i = 0; i < N; i++) scanf("%d %d", &r[i], &w[i]);
        best = 1000000000;
        int book_t[10] = {0};
        solve(0, 0, 0, 0, book_t, 0, 0);
        printf("%d\n", best);
    }
}

