#define INF 1000000000

static int max(int a, int b) { return a > b ? a : b; }
static int min(int a, int b) { return a < b ? a : b; }

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        int *A = (int *)malloc((n + 1) * sizeof(int));
        int *B = (int *)malloc((n + 1) * sizeof(int));
        int sumA = 0, sumB = 0;

        for (int i = 1; i <= n; i++) {
            scanf("%d %d", &A[i], &B[i]);
            sumA += A[i];
            sumB += B[i];
        }

        int S = sumA;
        int *dp = (int *)malloc((S + 1) * sizeof(int));
        for (int i = 0; i <= S; i++) dp[i] = INF;
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            int *ndp = (int *)malloc((S + 1) * sizeof(int));
            for (int j = 0; j <= S; j++) ndp[j] = INF;

            for (int x = 0; x <= sumA; x++) {
                if (dp[x] == INF) continue;

                /* Ami reads book i first, then Mami reads it */
                if (x + A[i] <= S) {
                    int finishMami = max(dp[x], x + A[i]) + B[i];
                    if (finishMami < ndp[x + A[i]]) ndp[x + A[i]] = finishMami;
                }

                /* Mami reads book i first, then Ami reads it */
                int finishMami2 = dp[x] + B[i];
                if (finishMami2 < ndp[x]) ndp[x] = finishMami2;
            }

            free(dp);
            dp = ndp;
            sumA -= A[i];
        }

        int answer = INF;
        int processedA = 0;
        for (int i = 1; i <= n; i++) processedA += A[i];

        /* Actually processedA == original sumA, so just scan all states */
        for (int x = 0; x <= S; x++) {
            if (dp[x] == INF) continue;
            answer = min(answer, max(x, dp[x]));
        }

        printf("%d\n", answer);

        free(dp);
        free(A);
        free(B);
    }
    return 0;
}

